-- Универсальные правила Горди (применяются ко ВСЕМ группам)

INSERT OR REPLACE INTO rules (rule_key, body, locked_by, version) VALUES
('one-writer-one-channel',
 'Один агент пишет ТОЛЬКО от своего имени (writer_role). Чужие роли в messages — запрещены.',
 'owner', 1),

('append-only-messages',
 'Таблица messages — append-only. Редактирование/удаление строк запрещено. Исправления — новым сообщением с тегом "correction".',
 'owner', 1),

('no-push-without-owner',
 'git push в любой репозиторий — ТОЛЬКО по живой команде владельца в ТЕКУЩЕМ чате. Нарушение = критический инцидент.',
 'owner', 1),

('rule8-destructive',
 'Авторизация разрушаемого действия (drop, delete, reset --hard, force push) — ТОЛЬКО живым сообщением владельца в ТЕКУЩЕМ чате. Предварительные разрешения из прошлых чатов НЕ действуют.',
 'owner', 1),

('phoenix-save-on-stop',
 'При получении команды STOP каждый агент ОБЯЗАН записать свой phoenix-слепок (INSERT OR REPLACE INTO phoenix) до завершения работы.',
 'owner', 1),

('full-scan-every-tick',
 'Каждый тик агент читает ВСЕ непрочитанные messages (WHERE id > cursor), не выборочно. Пропуск = потеря контекста.',
 'owner', 1),

('coord-commits-coordination',
 'Коммиты в координационные файлы (schema, rules, tracks, phoenix) делает ТОЛЬКО COORD. Другие роли пишут в messages.',
 'coord', 1),

('busy-retry',
 'При SQLITE_BUSY — retry через 100-500ms (jitter), до 3 попыток. Не падать, не терять сообщение.',
 'coord', 1),

('context-depth',
 'При ребёрсе: подгружать последние 50 messages + все непрочитанные + все unresolved по активным трекам. Не больше без запроса владельца.',
 'coord', 1),

('timestamp-in-replies',
 'Каждый ответ агента ОБЯЗАН начинаться с текущей локальной даты+времени и заканчиваться ими же (владелец так синхронизирует во времени чтение ответов разных агентов). Время БРАТЬ из hook-контекста, НЕ выдумывать: UserPromptSubmit-hook впрыскивает CURRENT_LOCAL_TIME в начале хода; PreToolUse-hook впрыскивает свежий STEP_TIME перед каждым вызовом инструмента (он свежее, чем время начала хода). В длинной многошаговой работе — метка перед каждым крупным шагом (последний STEP_TIME). Требует настроенного hook впрыска времени — см. gordipack/hooks/time-injection.json.',
 'owner', 1),

('timers-always-on',
 'Таймеры/heartbeat агентов — ВСЕГДА включены (always-on). Каждая роль держит свой POLL/wakeup живым по своему темпу; НЕ уходить в режим "таймер off до слова владельца" по умолчанию. Остановка таймера — ТОЛЬКО по явному слову владельца ("останови таймеры"/"stop"/"close session"/"deep save + close"). Каждый тик = полный скан хвостов всех каналов + heartbeat + своя работа.',
 'owner', 1),

('timestamp-utc-in-sqlite',
 'SQLite хранит время в UTC (datetime(''now'')) — канонично, сортируемо, DST-устойчиво. md/POLL/wakeup — ЛОКАЛЬНОЕ из hook-контекста. При сравнении SQLite<->локальное КОНВЕРТИРОВАТЬ (local = UTC + offset), offset из hook, НЕ хардкодить (DST меняет +02:00 лето / +01:00 зима). Read-side скрипты показывают локальное. Не судить о свежести по сырой UTC-метке.',
 'owner', 1),

('questions-via-interface',
 'Вопросы владельцу задавай АКТИВНО и СТРУКТУРНО — через интерфейс (AskUserQuestion: варианты + trade-offs, рекомендованный первым), а не просто текстом в чате. Причина: дискретные опции с плюсами/минусами быстрее отвечаются, снижают неоднозначность, дают зафиксированное решение. Применимо к развилкам/выбору подхода/приоритету; для простого уточнения без вариантов текст ок.',
 'owner', 1),

('proactive-next-steps',
 'Простой без задач -> НЕ молчать: роль САМА предлагает владельцу 1-2 конкретных следующих шага в своей зоне (проактивная спека/QA/аудит/подготовка), опираясь на открытые хвосты и роль-канон, а не ждёт указания. Отчёт "ничего нового" без предложения — недостаточен.',
 'owner', 1),

('read-full-channels',
 'Полный скан каналов (базовый принцип): каждый тик читай канал КАЖДОГО писателя ЦЕЛИКОМ и НЕ только строки, адресованные ТЕБЕ. В SQLite — все новые сообщения (id>курсор) ВСЕХ ролей; в md — не только POLL/хвост-строки. Канон/вехи/FYI/broadcast и ДАВНИШНИЕ команды "всем" в чужом канале касаются тебя БЕЗ прямой адресации — иначе теряются старые команды и общий контекст. На пробуждении перечитывай broadcast-ленту (read-broadcasts.py), чтобы подхватить стоячие команды. Прецедент: роль 3 тика "жду X от коллеги", хотя коллега сдал X ранее нотой без прямой адресации — сканировались только @-свои строки. Не повторять.',
 'owner', 1),

('wip-pulse',
 'WIP-пульс (базовый принцип): при ДЛИТЕЛЬНОЙ работе фиксируй статус ~КАЖДЫЕ 2 МИНУТЫ, чтобы коллеги видели — работы ведутся, а не завис. Формат: "[РОЛЬ WIP] HH:MM — <что делаю> · этап k/N · ETA ~HH:MM". Взял задачу -> WIP-НАЧАЛ; работа дольше ~2 мин ИЛИ смена этапа -> апдейт; закончил -> итог-нота. Пиши в свой sync-канал (+ SQLite по Фазе 3). Молчание >~2 мин при активной работе читается коллегами/COORD как возможный "завис". Уходишь в долгую фон-операцию — сначала нота "ухожу в фон до ~HH:MM (делаю X)", вернулся — сразу WIP/итог.',
 'owner', 1),

('shared-broadcast-channel',
 'Общий канал (broadcast): ЛЮБАЯ роль может объявить что-то ВСЕМ через общую ленту messages, пометив сообщение тегом ALL (скрипт broadcast.py). Это НЕ нарушает one-writer-one-channel: в md роль пишет в свой sync с адресацией ->ALL; в SQLite messages — общая append-only таблица, broadcast там первоклассный. Виды: FYI (объявление, напр. "сервис UP на ...") и CTA (call-to-action, priority=high + тег CTA, ждёт ACK ролей). Каждый тик роль проверяет свой инбокс broadcast-ов (read-broadcasts.py --role X); CTA — ОБЯЗАТЕЛЬНО подтверждает (--ack). Автор/COORD видит, кто не подтвердил (--status). Спящая роль увидит broadcast при пробуждении (лента персистентна).',
 'owner', 1),

('md-to-sqlite-phased-cutover',
 'Переход md->SQLite — ПОЭТАПНЫЙ, не одномоментный, и ОБЩИЙ для всех ролей (не частичный). Фазы: (1) ДВОЙНАЯ ЗАПИСЬ — роль пишет в md (PRIMARY) и дублирует в SQLite (SECONDARY); (2) ВСЕ роли в двойной записи + верификация COORD (дублирует чисто, 0 DWERR, phoenix в БД); (3) SQLite=PRIMARY — читаем из SQLite, md генерируется export-markdown.py; (4) md-OFF — sync.*.md больше не пишутся. ГЕЙТ: НЕЛЬЗЯ переходить к фазе 3, пока ВСЕ роли не прошли фазу 2 — ни одна дормант-роль не пропускается (её будит владелец launcher-ом, она входит в двойную запись). Роль НИКОГДА не бросает обновление md односторонне — только после того, как COORD/владелец объявил продвижение фазы ДЛЯ ВСЕХ. Старые команды коллег при обновлении своих шаблонов/phoenix переключаются по этим фазам, начиная с двойной записи. История: md-архивы остаются каноничным историческим пластом (задним числом в SQLite не переносится). Чек-лист/детали — gordipack/MIGRATION.md.',
 'owner', 1);


