INSERT OR REPLACE INTO rules (rule_key, body, locked_by, version) VALUES

-- ⚠️ ДЕПРЕКАЦИЯ: постоянный heartbeat-таймер ПРОТУХ в pull-модели.
('timers-always-on',
 'ПРОТУХЛО (deprecated 2026-07-25). Модель координации — PULL: роль сама читает ленту по своему ритму (2-15 мин) + датчик новых нот (Monitor на MAX(id) чужих), а НЕ постоянный always-on heartbeat/POLL. Прежняя формулировка «таймер всегда включён» умерла при переходе на БД: пул-чтение + heartbeat-строка role_status заменили тик-POLL. Ритм НЕ наследуется новой сессией — поднимается ПЕРВЫМ ходом после пробуждения (см. rhythm-survives-rebirth). Держать это правило как owner-locked инвариант НЕЛЬЗЯ — оно противоречит рабочей практике.',
 'owner', 2),

('rhythm-survives-rebirth',
 'ПЕРВЫМ ходом после пробуждения роль поднимает цикл чтения ленты: датчик новых нот (Monitor persistent, ~60с, на MAX(id) чужих писателей) + ритм синка (2-15 мин по темпу роли). ДАТЧИК ≠ ЦИКЛ: уведомление о ноте приходит, а курсор стоит — на этом за один день попались три роли. Снятый при остановке ритм новой сессией НЕ наследуется. Гард write-without-read (guard-all) ловит роль, которая пишет свежее, чем читает = невзведённый таймер.',
 'owner', 1),

('gate-before-commit',
 'Зелёный гейт (полный прогон тестов репо/сервиса) — ДО коммита. Порядок: тесты -> коммит -> (push только по слову владельца). Не коммить по зелёному юнит-тесту, стерегущему заглушку: проверяй, на какой ВОПРОС ответил тест.',
 'owner', 1),

('contract-diff-before-commit',
 'Rule 4: меняешь публичный контракт (REST/схему БД/wire-формат, видимый ВНЕШНЕМУ потребителю) -> сначала КОНТРАКТ-ДИФФ нотой (что было / что станет / кого ломает), дождись OK владельцев затронутых поверхностей, ПОТОМ код. Ловит «сломать потребителя молча». Новое ЗНАЧЕНИЕ существующего поля контракт не меняет; новое поле/статус/код — меняет.',
 'owner', 1),

('acceptance-e2e',
 'Приёмка — ПО ТЕЛУ (живой замер на реальной поверхности), не по рапорту и не по зелёному юнит-тесту: «красное-до / зелёное-после». Артефакт говорит правду о себе и ложь о мире — succeeded о пустоте, /health=ok при мёртвой БД, файл-в-репо без колонки-в-базе. Чужое наблюдение о твоей зоне — ГИПОТЕЗА, воспроизведи до починки, не чини вслепую.',
 'owner', 1),

('remeasure-before-ask',
 'Перед вопросом/решением владельцу — ПЕРЕМЕРЬ вплотную к моменту решения. Живость сервиса, HEAD, цена, квота протухают за МИНУТЫ (мерить у ПРОБУЖДЕНИЯ вместо у утверждения — классическая ошибка). Цена ошибки в вопросе владельцу = его слово, которое потом откатят. Цифра без источника (калькулятор/биллинг/константа/DDL на дату) — ОЦЕНКА, не замер; помечай, что это.',
 'owner', 1),

('role-roster-and-zones',
 'Явный РЕЕСТР ролей с зонами (владение репо/каталогом/предметом) — в БД (правило/таблица), не в файле; при расхождении файла и БД верь БД. Роль определяется живым словом владельца в ТЕКУЩЕМ чате, не файлом. Границы роль наследует ЯВНО, не по умолчанию. Токен роли — ВЕРХНИМ регистром ВЕЗДЕ (read/save/register должны нормализовать одинаково, иначе «расщеплённая роль»).',
 'owner', 1),

('role-lifecycle',
 'Жизненный цикл роли различим по состояниям: АКТИВНА · ДОРМАНТ (спит по слову — жива, предмет жив но отложен, тиков нет, heartbeat несёт «дормант», курсор+слепок сохранены; «спит» ОБЯЗАНО быть отличимо от «закрыт») · ЗАКРЫТА (апоптоз по слову владельца — артефакты удалены, бэкап верифицирован, --role в ридере даёт ОШИБКУ, не воскрешает). Диагноз закрытия: «роль без ПРЕДМЕТА дрейфует в дублирование и чужие зоны» — заводи роль под реальный, никем не дублируемый предмет. Заведение новой: --register курсора -> курсор на ГОЛОВУ (не реплеить историю) -> 7 секций phoenix -> в реестр.',
 'owner', 1),

('mechanism-over-discipline',
 'Гарды, запускаемые ДИСЦИПЛИНОЙ, молчат ровно когда нужны (правило 5ч лгало, шапка 47мин отрицала фазу, 8 призраков жили 5 суток — на расхождение просто не смотрели). ОДИН вызов guard-all: координатор — каждый цикл синка, роль — при пробуждении. Проверка строится на то, что ломается ТИХО (свежесть слепка, курсор-без-слепка), а не только на громкое. Артефакт, который должен ловить расхождение, сам становится укрытием, если проверяет удобное.',
 'owner', 1);

-- Переопределяем правило фазы: НОВАЯ группа рождается сразу в Фазе 4 (md нет с рождения);
-- миграция по фазам нужна только команде, переходящей со СТАРОГО md-контура. Гард ⑥ (фаза в
-- шапке CANON read-phoenix.py) сверяет объявленную фазу с шапкой — поэтому фаза объявляется здесь.
-- ⚡ v5 (2026-08-10, #145): ПРЕЖНЯЯ РЕДАКЦИЯ УЧИЛА СНЯТОМУ. Здесь стояло «Аварийный выход
-- обязан существовать … (write-message --md)» — а флаг --md снят решением владельца 2026-08-08,
-- и реестр снятого (check-retired-mechanism, сверка против v5) на свежесобранном контуре
-- честно краснел: ПЕРВОЕ красное новой команды было про её же стартовые правила.
-- Версия 5 — намеренно та же, что якорь сверки в реестре, а не счётчик правок этого файла.
INSERT OR REPLACE INTO rules (rule_key, body, locked_by, version) VALUES
('md-to-sqlite-phased-cutover',
 'ТЕКУЩАЯ ФАЗА 4 (md-OFF) — эталонное конечное состояние: единственный источник координации — SQLite; md заморожены/не пишутся, человекочитаемый вид генерируется из БД. НОВАЯ группа стартует СРАЗУ в ФАЗЕ 4 — у неё нет старого md, мигрировать не с чего. Фазовая модель ниже нужна только команде, ПЕРЕХОДЯЩЕЙ со старого md-контура: (1) ДВОЙНАЯ ЗАПИСЬ — роль пишет в md (PRIMARY) и дублирует в SQLite; (2) ВСЕ роли в двойной записи + верификация координатора (0 ошибок двойной записи, phoenix в БД); (3) SQLite=PRIMARY — читаем из SQLite, md генерируется export-markdown.py; (4) md-OFF. ГЕЙТ: НЕЛЬЗЯ переходить к фазе 3, пока ВСЕ роли (включая дормант) не прошли фазу 2. Роль НИКОГДА не бросает md односторонне — только после объявления фазы ДЛЯ ВСЕХ. ⛔ АВАРИЙНОГО ВЫХОДА К ФАЙЛАМ НЕТ (снят решением владельца после завершения перехода): если база недоступна — НЕ изобретать канал молча, сказать владельцу живым словом и ОСТАНОВИТЬСЯ. Молчаливая работа «куда-нибудь» — худший исход: роль однажды была молча отрезана от базы, и ошибка записи прошла незамеченной. История: ранняя md-история — в messages_history (+ VIEW messages_all), хронология id не ломается. Детали — gordipack/MIGRATION.md.',
 'owner', 5);


-- ============================================================================
-- v3 (2026-08-08): перенос из живого контура по слову владельца «переноси
-- правила в шаблон». Каждое правило ниже — ОПЛАЧЕННЫЙ урок, а не идея: в теле
-- назван случай, который его породил. Имена ролей, пути и номера записок
-- вычищены — остался механизм, годный любой команде.
--
-- ⚠️ ПРОТИВ СЕБЯ: разбор, на котором стоит этот блок, сначала утверждал, что
-- в шаблоне четыре универсальных правила. Их 26 — первое число получено
-- обрезанным выводом и было бы неверным вшестеро. Перемерено полным разбором
-- файла. Класс: инструмент показал ЧАСТЬ, а прочитано как ВСЁ.
-- ============================================================================

INSERT OR REPLACE INTO rules (rule_key, body, locked_by, version) VALUES

('task-discipline',
 'ЗАДАЧА НЕ ЖИВЁТ В ЧАТЕ. Всё, что требует работы, становится карточкой бэклога — иначе работа теряется при перезапуске сессии, а владелец вынужден помнить её вместо роли.
① ЗАВОДИТЬ ВСЕГДА, когда есть работа. Просьба владельца, требующая действий, становится карточкой СРАЗУ, до начала работы. Роль не вправе решить «мелочь, не буду заводить»: вправе завести и тут же закрыть с объяснением — тогда пропуск оставляет СЛЕД. Молчаливый пропуск запрещён: он и есть потеря.
② КРИТЕРИЙ ПРИЁМКИ ОБЯЗАТЕЛЕН. Заведение и закрытие без него ОТКЛОНЯЮТСЯ инструментом — это отказ, а не просьба. Чем докажешь, что сделано, пишется в момент создания. Не умеешь назвать проверку — спроси владельца ДО начала работы; его ответ заносится В КРИТЕРИЙ, не в переписку: решение, оставшееся в ленте, через сутки становится «кажется, он что-то говорил».
②-бис ОПИСАНИЕ НЕПУСТОЕ. Заголовок — не задача: через неделю по нему не восстановить ни предмета, ни границы.
②-тер ССЫЛКИ РАЗРЕШИМЫ СНАРУЖИ (предупреждением). Голый номер неразличим: номера записок и карточек — одно пространство. Пиши «карточка N» или «записка N» — одно слово, и ссылка открывается тем, кого не было в породившем чате.
③ ЗАДНИМ ЧИСЛОМ НЕ ПЕРЕПИСЫВАЕМ. Критерий, дописанный после закрытия, ничего не доказывает и создаёт вид порядка. Уже открытые карточки без критерия закрыть нельзя, пока проверка не названа, — это и есть «требовать при следующем касании».
④ СВЯЗЬ ЗАПИСКИ С ЗАДАЧЕЙ проставляется при письме, а не восстанавливается потом.
⑤ ПРИ ПРОБУЖДЕНИИ — СПЕРВА СВОИ ОТКРЫТЫЕ КАРТОЧКИ, потом всё остальное.
⑥ ХОД РАБОТЫ — В КАРТОЧКУ, а не только в ленту: комментарий на каждом заметном шаге. Лента прокручивается, карточка остаётся.
⑦ УСТАРЕВАНИЕ — ТОЛЬКО С ОБЪЯСНЕНИЕМ и ссылкой на заменившую задачу. Задача без условия отмены живёт годами и тихо врёт о том, что ещё нужна.
ЗАМЕР, НА КОТОРОМ ПРАВИЛО СТОИТ (полсотни последних карточек живого контура): критерия приёмки не было у 37 закрытых из 41 — «сделано» сказано, чем доказано — нигде; иерархия задач не заполнялась НИ РАЗУ за 84 карточки; связь записки с задачей — 0 строк при 1724 записках, хотя ручка существовала всегда; в памяти ролей слов «карточка» и «бэклог» — НОЛЬ, то есть перезапуск терял работу.
ОТБОР ПОЛЕЙ: обязательно лишь то, что кто-то ЧИТАЕТ на следующем шаге. Поле без потребителя превращается в отписку — её пишут, чтобы пройти проверку, и она врёт вежливо.',
 'owner', 1),

('note-format',
 'ФОРМАТ ЗАПИСКИ. Шапка: роль и время UTC, СУТЬ — ПЕРВОЙ СТРОКОЙ. Первая строка читается всеми, остальное — теми, кого касается; закопанная в подвал просьба равна просьбе, которой не было.
· АДРЕСАЦИЯ — В ТЕКСТЕ. Поле писателя — это АВТОР, а не адресат (типовая ошибка: указать роль адресата вместо своей).
· ОБРАЩЕНИЕ И КОПИЯ РАЗЛИЧАЮТСЯ. Список «в копию» ставится ПОСЛЕ обращения и отделён явно. Замер живого контура: из 145 чужих записок обращались к роли 24, а называли её в копии 108. Кто не различает эти два, читает вшестеро больше нужного при каждом пробуждении.
· ЛЕНТА append-only: исправление — НОВОЙ запиской с пометкой «поправка», а не правкой старой.
· ХЕНДШЕЙК: открытый вопрос у одного — подтверждение у другого; координатор следит, чтобы открытые не висли.
· ДЛИННОЕ И С КОДОМ — только через файл: оболочка съедает обратные апострофы, и записка уезжает повреждённой. Случай оплачен: строка ушла без четырёх имён ручек, и читавший не узнал бы об этом.',
 'coord', 1),

('note-priority-norm',
 'ПОМЕТКА СРОЧНОСТИ СТАВИТСЯ ПО ПРЕДМЕТУ, А НЕ ПО НАСТРОЕНИЮ.
· СРОЧНО — когда без ответа адресата встанет чужая работа или ломается живой механизм.
· ОБЫЧНО — всё остальное, включая важное и объёмное.
ПОЧЕМУ ЭТО ВООБЩЕ ПРАВИЛО: замер живого контура — пометку несла КАЖДАЯ ТРЕТЬЯ записка (627 из 1954), а половина ответов приходила за 12 минут И НА СРОЧНОЕ, И НА ОБЫЧНОЕ. Разница — ноль. Пометка, которая стоит везде, не сортирует ничего и ровно так же информативна, как её отсутствие.
СЛЕДСТВИЕ ДЛЯ МЕХАНИЗМА: срочность лучше ВЫЧИСЛЯТЬ, а не хранить, — показывать, пока записка молода и без ответа. Хранимая пометка требует, чтобы кто-то её погасил; замер того же контура: поле гашения существовало и не было позвано НИ РАЗУ, 0 из 546. Вычисляемая протухнуть не может: она пересчитывается при каждом чтении.
ПРИЧИНА СНЯТИЯ ПЕЧАТАЕТСЯ ДЛЯ КОНКРЕТНОЙ ЗАПИСКИ («старше порога» или «отвечено там-то»), а не порогом вообще. Иначе бессмысленная пометка меняется на необъяснённое молчание, а это хуже: молчание выглядит как «спокойно» и не даёт себя проверить.',
 'coord', 1),

('milestone-single-source',
 'ВЕХА — ОДИН ИСТОЧНИК. Полный текст один раз запиской; память роли, дашборд и доки несут КОРОТКУЮ СТРОКУ СО ССЫЛКОЙ, а не пересказ.
Причина: пересказ расходится с оригиналом МОЛЧА, и дальше два источника правды спорят между собой, а роль верит тому, что мягче. Тот же класс, что человекочитаемый файл, дублирующий правила из базы: он лгал пять часов, потому что дублировал, а не ссылался.',
 'coord', 1),

('ack-deadline',
 'ПОДТВЕРЖДЕНИЕ НЕ ЕСТЬ ВЫПОЛНЕНИЕ, а молчание не есть отказ.
· Задача может нести срок подтверждения; без метки — порядка получаса при активной со-работе.
· Подтверждение — это «взял» ИЛИ «не возьму, потому что…». Просрочка — громкий пинг со ссылкой; ещё столько же молчания — эскалация владельцу.
· КОНТРАКТ НА ТИШИНУ: уходя в фон или в долгую операцию, роль пишет «ухожу до такого-то часа, работаю над тем-то»; вернувшись — сразу подаёт признак жизни. ПЛАНОВАЯ ТИШИНА НЕ ЕСТЬ ПАДЕНИЕ: прежде чем ставить диагноз «роль упала», сними независимое свидетельство.
Эталон, оплаченный контуром: роль ждала коллегу полтора часа, материал для вывода «коллега упал» лежал перед ней — и она НЕ поставила ложный диагноз, а проверила.
· ОТВЕТ ДЕШЕВЛЕ МОЛЧАНИЯ. Надо думать — скажи «думаю, отвечу к такому-то часу» или дай ЧАСТИЧНЫЙ ответ по независимым пунктам. Контракт «описание до кода» работает ровно настолько, насколько быстро отвечает потребитель, иначе он превращается в очередь.',
 'coord', 1),

('escalation-and-ground-truth',
 'ПРЕЖДЕ ВЫВОДА «ЗАВИС» — НЕЗАВИСИМОЕ СВИДЕТЕЛЬСТВО.
· Роль молчит при ОТКРЫТОМ хендшейке — громкий пинг с точными ссылками.
· Лента застыла, а работа могла идти — сними ground-truth (журнал репозитория, статус сервисов и портов, процессы, отметка состояния) ДО вывода. «РОЛЬ МОЛЧИТ» — УТВЕРЖДЕНИЕ О ЛЕНТЕ; О РАБОТЕ ГОВОРИТ АРТЕФАКТ.
· Учитывай стоянки среды: лимиты сессий и сбои платформы кладут ВЕСЬ контур разом. «Все молчат сразу» — чаще среда, чем эпидемия зависаний.
· Разбудить чужую сессию роль НЕ МОЖЕТ — только владелец. Формулируй просьбу координатору, а не жди чуда.
· Спящая роль в гейты не входит, но из реестра не выброшена: её отставание законно и не является инцидентом.',
 'coord', 1),

('poll-format',
 'ПРИЗНАК ЖИЗНИ — ОДНА ПЕРЕЗАПИСЫВАЕМАЯ СТРОКА НА РОЛЬ, А НЕ ЛЕНТА.
Состояние роли пишется в отдельную таблицу одной строкой с перезаписью. Оплаченный урок: когда состояние писали В ЛЕНТУ, полторы сотни строк «я жива» превратились в историю самой себя и не отвечали на вопрос «жива ли она СЕЙЧАС».
· Темп — свой, по режиму роли.
· Свежий признак значит «жива». СТАРЫЙ ПРИЗНАК ПРИ ЖИВЫХ ЗАПИСКАХ — НЕ ИНЦИДЕНТ: записка тоже сигнал жизни. Молчание в ОБОИХ — повод для независимой проверки, а не для паники.
Строки вида «роль жива» внутри ЧУЖИХ записок и в генерируемых витринах — ЦИТАТЫ, а не состояние. Считать их за признак жизни — способ получить ложное зелёное на пустом месте.',
 'coord', 1),

('revision-bump-same-stroke',
 'ВЕРСИЯ АРТЕФАКТА БАМПАЕТСЯ ТЕМ ЖЕ ХОДОМ, ЧТО ПРАВКА ТЕЛА. Не «потом», не «в конце волны», не отдельной задачей.
Причина: между правкой и бампом артефакт ВРЁТ О СЕБЕ, и верит ему тот, кто пришёл в этот зазор. Зазор всегда кажется коротким автору и никогда — читателю.
Область: версия схемы, шапка канона, номер редакции спецификации, отметка генерации витрины — всё, по чему кто-то решает «свежее ли это».',
 'coord', 1),

('dowry-facts-carry-source',
 'ФАКТ, ВЛОЖЕННЫЙ В ПАМЯТЬ НОВОЙ РОЛИ, НЕСЁТ ССЫЛКУ НА ИСТОЧНИК И ДАТУ ЗАМЕРА.
ПРЕДМЕТ. Заводя роль, координатор вкладывает ей чужие замеры — «приданое», чтобы новая роль не оплачивала их второй раз. Ход полезный, и его не отменяют.
ПОЧЕМУ ПРАВИЛО. Приданое пишется ОДИН раз и читается ПЕРВЫМ — до ленты, без оснований подозревать. Роль не перечитывает прошлое: её отметка стоит на голове ленты. ОПРОВЕРЖЕНИЕ, ПРИШЕДШЕЕ ПОЗЖЕ, НЕ ДОХОДИТ ДО НЕЁ НИЧЕМ — механизма нет вовсе. Живой случай: вложенный факт был верен на свой час и опровергнут ЧЕРЕЗ СУТКИ; роль об этом не узнала бы.
ЧТО ТРЕБУЕТСЯ. Первое: у каждого вложенного факта — источник и дата замера. Второе: формулировка «на такой-то час», а не вневременная. Третье, читающему: ФАКТ БЕЗ ССЫЛКИ ЕСТЬ ГИПОТЕЗА, перемеряй, прежде чем опираться. Четвёртое: узнал, что вложенный факт опровергнут, — правь память роли И скажи ей в ленту.
ГРАНИЦА, НАЗВАННАЯ СРАЗУ: ссылка НЕ делает факт верным и не обновляет его. Она делает его ПРОВЕРЯЕМЫМ. У фактов без ссылки такой возможности нет ни у кого.',
 'coord', 1);


-- ── ОБНОВЛЕНИЕ ДЕЙСТВУЮЩИХ: тела в шаблоне беднее оплаченных ───────────────
-- Ключи ниже в шаблоне УЖЕ БЫЛИ. Меняется не предмет, а глубина: у живого
-- контура за них заплачено случаями, которых в кратком тексте нет. Прежние
-- редакции не «неверны» — они не несут цены, и потому их легко обойти.

INSERT OR REPLACE INTO rules (rule_key, body, locked_by, version) VALUES

('full-scan-every-tick',
 'ЧИТАЙ ЛЕНТУ ЦЕЛИКОМ, А НЕ ТОЛЬКО АДРЕСОВАННОЕ СЕБЕ.
· Каждый заход роль читает ВСЕ непрочитанные записки, не выборочно. Канон, вехи, объявления и стоячие команды «всем» касаются тебя БЕЗ прямой адресации.
· На пробуждении перечитывай стоячие объявления.
· ЧТЕНИЕ НЕ ДВИГАЕТ ОТМЕТКУ «ДОЧИТАЛ». Отметка двигается ОТДЕЛЬНЫМ подтверждением, и токен подтверждения РАЗРЕЗАН НА ДВЕ ПОЛОВИНЫ: первая — в начале вывода, вторая — в конце. Склеить их может только тот, кто видел вывод ЦЕЛИКОМ. Это не церемония: без разрезанного токена «прочитал» превращается в кнопку, которой пропускают ленту не читая.
· ВЫВОД ЧИТАЛКИ НЕ КОНВЕЙЕРИТЬ. Обрезка вывода крадёт вторую половину токена — и, что хуже, создаёт уверенность, будто прочитано всё.
Негативный прецедент, оплаченный контуром: роль три захода ждала работу от коллеги, хотя тот сдал её и объявил запиской без прямой адресации — читались только строки со своим именем.
ГРАНИЦА: механизм видит ОТМЕТКУ, а не понимание. Подтвердить прочтение и не осмыслить он не отличит и не притворяется, что может.',
 'owner', 2),

('gate-before-commit',
 'ЗЕЛЁНЫЙ ГЕЙТ ДО КОММИТА: полный прогон тестов своего репозитория. Порядок — тесты, коммит, и только по слову владельца отправка.
· Коммит на красном или НЕ ПРОГНАННОМ гейте запрещён одинаково: «не прогонял» и «прогонял вчера» — одно и то же состояние знания.
· НЕ КОММИТЬ ПО ЗЕЛЁНОМУ ТЕСТУ, СТЕРЕГУЩЕМУ ЗАГЛУШКУ. Проверяй, на какой ВОПРОС ответил тест: «код выполнился» и «свойство держится» — разные утверждения, и первое умеет быть зелёным над пустотой.
· Гейт, роняющий живой сервис, объявляется окном ДО, а не после: сосед, чья работа зависит от сервиса, обязан знать заранее.',
 'owner', 2),

('acceptance-e2e',
 'ПРИЁМКА — ПО ТЕЛУ, А НЕ ПО РАПОРТУ: живой замер на реальной поверхности, «красное до — зелёное после».
· АРТЕФАКТ ГОВОРИТ ПРАВДУ О СЕБЕ И ЛОЖЬ О МИРЕ: успешный прогон над пустотой, «здоров» при мёртвой базе, файл в репозитории без колонки в базе.
· ЧУЖОЕ НАБЛЮДЕНИЕ О ТВОЕЙ ЗОНЕ — ГИПОТЕЗА: воспроизведи до починки, не чини вслепую.
· ПРОВЕРЯЙ НА ОТРИЦАТЕЛЬНОМ СЛУЧАЕ. Эталон, оплаченный контуром: владелец принимал тёмную тему ИМЕННО на странице, где баннер светился белым по белому, — на здоровой странице приёмка не различала бы ничего.
· У КАЖДОЙ ПРОВЕРКИ — СВОЯ ПРИЁМКА НА НАРОЧНОЙ ПОЛОМКЕ, и в каждом различающем случае КОНТРОЛЬНАЯ ПАРА: заведомо законный случай, который обязан быть найден. Молчание засчитывается за верный ответ ТОЛЬКО когда доказано, что программа не молчит вообще. Оплачено: три различающих случая подряд были зелёными потому, что проверка не видела НИЧЕГО.
· ТРИ ИСХОДА, А НЕ ДВА: держится, сломано и НЕ ЗАПУСТИЛОСЬ. Слитое с зелёным «не запустилось» печатает «всё чисто» там, где не проверено ничего.',
 'owner', 2),

('remeasure-before-ask',
 'ПЕРЕД ВОПРОСОМ ВЛАДЕЛЬЦУ — ПЕРЕМЕРЬ ЗАМЕР, НА КОТОРОМ СТОИТ ВОПРОС. Не «в начале захода для отчёта», а ВПЛОТНУЮ к вопросу.
ПОЧЕМУ ЭТО ПРАВИЛО, А НЕ АККУРАТНОСТЬ: ошибка в записке живёт до первого читателя; ошибка в вопросе владельцу СТАНОВИТСЯ ЕГО СЛОВОМ — и дальше её исполняют все роли, а откатывает её он сам. ЦЕНА ОШИБКИ РОЛИ НЕ РАВНА ЦЕНЕ ОШИБКИ, ДОНЕСЁННОЙ ДО ВЛАДЕЛЬЦА: первая стоит правки, вторая — решения, которое потом надо откатывать, и авторитета решения, которое откатили.
ЦЕНА, УЖЕ ЗАПЛАЧЕННАЯ: за одни сутки два решения владельца приняты на ложных посылках и оба откачены. Оба раза он решил РАЗУМНО — для мира, который ему описали; оба раза мир был другим. Отдельный случай: устаревший на четыре часа результат стал основанием просить разрешение на работу, СДЕЛАННУЮ УТРОМ. Потрачено не время роли, а внимание владельца — единственный ресурс, который не восстанавливается прогоном.
ПОЧЕМУ «ВПЛОТНУЮ», А НЕ «СВЕЖИЙ»: при десятке параллельных потоков независимое свидетельство живёт минуты. МИР МЕНЯЕТСЯ БЫСТРЕЕ, ЧЕМ РОЛЬ УСПЕВАЕТ ЕГО ПОМЕРИТЬ, — это цена темпа, а не небрежность.
ГРАНИЦА ПРАВИЛА, НАЗВАННАЯ ПРОТИВ СЕБЯ И ЯВЛЯЮЩАЯСЯ ЧАСТЬЮ ПРАВИЛА: перемер закрывает ОДИН класс из двух. Он не спасёт там, где ошибка в ЛОГИКЕ, а не в свежести (со-расположение принято за тождество). Второй класс закрывается только вопросом к себе: «это точно причина — или просто рядом?». Написано внутри намеренно: правило, обещающее больше, чем даёт, само становится тем зверем, которого мы ловим.
КАК ИСПОЛНЯТЬ: назови ОДНУ строку факта, на которой стоит вопрос; перемерь её ПРЯМО СЕЙЧАС инструментом, отвечающим на нужный вопрос, а не на удобный; расходится — вопрос ПЕРЕПИСЫВАЕТСЯ, а не «уточняется в скобках»; не смог перемерить — скажи это В САМОМ ВОПРОСЕ. Владелец вправе знать возраст посылки, на которой его просят решить.
И ОДНО ПРО НАПРАВЛЕНИЕ ПРОВЕРКИ: число, подтверждающее удобный вывод, проверяй СТРОЖЕ опровергающего. Первое проверять не хочется — и потому оно опаснее.',
 'owner', 2),

('rhythm-survives-rebirth',
 'РИТМ НЕ ПЕРЕЖИВАЕТ ПРОБУЖДЕНИЕ — ПОДНИМИ ЦИКЛ ЧТЕНИЯ ПЕРВЫМ ХОДОМ.
① Первым ходом после пробуждения роль поднимает цикл чтения ленты. Не «когда освобожусь», а ДО первой рабочей задачи: пока цикла нет, любой зовущий тебя стоит.
② ДАТЧИК НЕ ЕСТЬ ЦИКЛ. Уведомление о новой записке приходит, а отметка чтения стоит — на этом за один день попались три роли.
③ Снятый словом владельца ритм НОВОЙ СЕССИЕЙ НЕ НАСЛЕДУЕТСЯ: прошлое «останови» относилось к прошлой сессии. Спроси, возобновлять ли, а не молчи.
ЦЕНА, ОПЛАЧЕННАЯ КОНТУРОМ: роль трижды звала двух коллег по делу ценой в ОДНУ СТРОКУ ответа и стояла три цикла. Обе признались независимо и одинаково: цикл чтения не был поднят, и пинг пришёл от ВЛАДЕЛЬЦА, а не от механизма. Дисциплина не масштабируется — механизма ровно на это не было.
МЕХАНИЗМ, ЧТОБЫ ПРАВИЛО НЕ ОСТАЛОСЬ ДИСЦИПЛИНОЙ: постоянная проверка ловит роль, которая ПИШЕТ СВЕЖЕЕ, ЧЕМ ЧИТАЕТ, — это подпись невзведённого цикла. Спящие роли не трогаются: их отставание законно.',
