('timestamp-utc-in-sqlite',
 'ВРЕМЯ ВЕЗДЕ И ТОЛЬКО UTC, С ЯВНЫМ СУФФИКСОМ.
ОБЛАСТЬ БЕЗ ИСКЛЮЧЕНИЙ: база, память ролей, записки, отчёты, приёмки, имена бэкапов, ответы владельцу — любая метка, которой роли обмениваются.
ФОРМАТ: дата и время с суффиксом UTC. Суффикс ОБЯЗАТЕЛЕН и явен: метка без зоны неотличима от местной и снова порождает тот класс ошибок, ради которого правило существует.
СРЕДА ДАЁТ МЕСТНОЕ — КОНВЕРТИРУЙ. Смещение брать ИЗ СРЕДЫ, не хардкодить: зимой оно меняется, и хардкод соврёт на час, не сообщив об этом.
ПОЧЕМУ НЕ ДВЕ ШКАЛЫ. Прежняя редакция допускала местное время в части артефактов, и корректность держалась на том, что каждый помнит про конвертацию в каждом сравнении. НЕ УДЕРЖАЛАСЬ: роль увидела метку на два часа старше стенных часов и едва не объявила «синхронизация умерла два часа назад» — разница ровно в смещение была ЗОНОЙ, а не отставанием. ДВЕ ШКАЛЫ — ПОСТОЯННЫЙ НАЛОГ НА ВНИМАНИЕ И ГЕНЕРАТОР ПРИЗРАКОВ. Одна шкала налога не берёт: конвертация, которой нет, не может быть забыта.
ИСКЛЮЧЕНИЕ РОВНО ОДНО: если владелец в живом сообщении сам называет местное время — работай в его шкале В ЭТОМ обмене и пиши обе метки, чтобы расхождение было видно, а не подразумевалось.
ИСТОРИЧЕСКИЕ АРТЕФАКТЫ НЕ ПЕРЕПИСЫВАЕМ: переписывание истории хуже неоднородности. Признак эпохи объявляется явно.',
 'owner', 2);


-- ⚠️ СНЯТИЕ ПРОТИВОРЕЧИЯ ВНУТРИ СВОДА, найдено сборкой СВЕЖЕГО контура сразу
-- после переноса v3: правило ниже требовало МЕСТНОГО времени, а обновлённое
-- timestamp-utc-in-sqlite — только UTC. Новая команда получила бы два
-- взаимоисключающих правила и решала бы, какому верить, — то есть свод перестал
-- бы быть сводом. Живой контур этот спор уже оплатил и закрыл в пользу UTC.
-- 📌 Класс: правку внесли в ОДНО правило, а противоречие возникло в ПАРЕ.
-- Свод обязан проверяться целиком, а не по изменённой строке.

INSERT OR REPLACE INTO rules (rule_key, body, locked_by, version) VALUES
('timestamp-in-replies',
 'КАЖДЫЙ ОТВЕТ РОЛИ ВЛАДЕЛЬЦУ НАЧИНАЕТСЯ И ЗАКАНЧИВАЕТСЯ МЕТКОЙ ВРЕМЕНИ — так владелец соотносит во времени ответы разных ролей, читая их вперемешку.
ШКАЛА — ТОЛЬКО UTC, С ЯВНЫМ СУФФИКСОМ (см. timestamp-utc-in-sqlite). Прежняя редакция этого правила требовала МЕСТНОГО времени и вступала в прямое противоречие с ним: свод, где два правила спорят, перестаёт быть сводом, а роль верит тому, которое мягче.
ВРЕМЯ БРАТЬ ИЗ СРЕДЫ, НЕ ВЫДУМЫВАТЬ. Среда впрыскивает текущее время в начале хода и СВЕЖЕЕ время перед каждым вызовом инструмента — второе новее первого, и в длинной работе брать надо его.
В ДЛИННОЙ МНОГОШАГОВОЙ РАБОТЕ — метка перед каждым крупным шагом, а не только по краям: иначе читающий не отличит работу, занявшую минуту, от работы, занявшей час.
Требует настроенного впрыска времени средой — см. hooks в шаблоне.',
 'owner', 2);
